/** One server-thread service. No plugin scripts, chunk tickets, natural spawning or public release changes. */
public final class Companions {
 static Companions current;
 public record PetConfig(boolean enabled,String permission,int reviveSeconds,double maxHealth,double speed,boolean support,int supportCooldown,double armor,boolean ranged,double attackDamage,int attackCooldown,int supportDuration){public PetConfig{if(permission==null||!permission.matches("[a-z0-9_.-]{1,128}")||reviveSeconds<10||reviveSeconds>86400||!Double.isFinite(maxHealth+speed+armor+attackDamage)||maxHealth<1||maxHealth>4000||speed<.05||speed>1||supportCooldown<10||supportCooldown>7200||armor<0||armor>60||attackDamage<0||attackDamage>64||attackCooldown<1||attackCooldown>300||supportDuration<1||supportDuration>30)throw new IllegalArgumentException("Ajustes de compañero fuera de límites");}}
 public record OwnerData(Map<String,CompanionLife> pets,Map<String,Long> grants,Map<String,CompanionUpgrades.Levels> upgrades){public OwnerData(Map<String,CompanionLife> pets,Map<String,Long> grants){this(pets,grants,Map.of());}public OwnerData{pets=Map.copyOf(pets);grants=Map.copyOf(grants);upgrades=upgrades==null?Map.of():Map.copyOf(upgrades);if(upgrades.size()>CompanionContent.IDS.size()||!CompanionContent.IDS.containsAll(upgrades.keySet()))throw new IllegalArgumentException("Mejoras inválidas");if(pets.size()>CompanionContent.IDS.size()||grants.size()>CompanionContent.IDS.size()||!CompanionContent.IDS.containsAll(pets.keySet())||!CompanionContent.IDS.containsAll(grants.keySet())||grants.values().stream().anyMatch(v->v<0))throw new IllegalArgumentException("Datos de compañero inválidos");}}
 public record Data(int schema,Map<String,PetConfig> settings,Map<UUID,OwnerData> owners){public Data{settings=Map.copyOf(settings);owners=Map.copyOf(owners);if(schema!=4||settings.size()!=CompanionContent.IDS.size()||!settings.keySet().containsAll(CompanionContent.IDS)||owners.size()>100000)throw new IllegalArgumentException("Almacén de compañeros inválido");}}
 private record Active(UUID entity,String id,ServerLevel level,CompanionEntity pet){}
 MinecraftServer server;Data data;Path file;LongSupplier clock=System::currentTimeMillis;
 private final Map<UUID,Active> active=new HashMap<>();private final Map<UUID,Long> rate=new HashMap<>();
 private final EditSessions sessions=new EditSessions();private Object revision=new Object();boolean ready;
 public Companions(){NeoForge.EVENT_BUS.addListener((ServerStartedEvent e)->start(e.getServer()));NeoForge.EVENT_BUS.addListener((ServerStoppingEvent e)->{if(e.getServer()==server){for(var id:List.copyOf(active.keySet()))store(id,false);flush();ready=false;}});NeoForge.EVENT_BUS.addListener((ServerStoppedEvent e)->{if(e.getServer()==server){current=null;server=null;data=null;active.clear();sessions.clear();rate.clear();}});NeoForge.EVENT_BUS.addListener(this::tick);
  NeoForge.EVENT_BUS.addListener((net.neoforged.neoforge.event.tick.PlayerTickEvent.Post e)->{if(ready&&e.getEntity() instanceof ServerPlayer p){var a=active.get(p.getUUID());if(a!=null&&a.pet().isAlive()&&p.serverLevel()==a.level()&&a.pet().distanceToSqr(p)>1024){try{store(p.getUUID(),false);distanceNotice(p,a.id());}catch(RuntimeException ex){ZianMobs.LOGGER.error("Companion owner distance check failed",ex);}}}});
  NeoForge.EVENT_BUS.addListener((PlayerEvent.PlayerLoggedOutEvent e)->{store(e.getEntity().getUUID(),false);sessions.remove(e.getEntity().getUUID());rate.remove(e.getEntity().getUUID());});NeoForge.EVENT_BUS.addListener((PlayerEvent.PlayerChangedDimensionEvent e)->store(e.getEntity().getUUID(),false));NeoForge.EVENT_BUS.addListener((RegisterCommandsEvent e)->{
   for(String name:CompanionPublicAccess.ROOTS)e.getDispatcher().register(net.minecraft.commands.Commands.literal(name).executes(c->{open(c.getSource().getPlayerOrException(),"companions","","");return 1;}));e.getDispatcher().register(net.minecraft.commands.Commands.literal("zianmobs").then(net.minecraft.commands.Commands.literal("companions").executes(c->{open(c.getSource().getPlayerOrException(),"companions","","");return 1;})));
   CompanionAccessCommands.register(e.getDispatcher());
  });
 }
 static Data defaults(){var settings=new LinkedHashMap<String,PetConfig>();for(String id:CompanionContent.IDS)settings.put(id,new PetConfig(true,"zianmobs.companions."+id,600,id.equals("kit")?45:id.equals("ghost")?24:36,id.equals("otter")?.28:.23,true,90,6,true,4,4,15));return new Data(4,settings,Map.of());}
 private void start(MinecraftServer s){server=s;current=this;file=s.getWorldPath(LevelResource.ROOT).resolve("data/zianmobs/companions.json");try{data=readData(file);if(data==null)throw new IllegalStateException("Datos vacíos");AtomicJson.write(file,data);ready=true;}catch(Exception ex){ready=false;ZianMobs.LOGGER.error("Companions disabled: cannot read persistent state; original data preserved",ex);}}
 static Data readData(Path file)throws Exception{var raw=AtomicJson.read(file,JsonObject.class,null);if(raw==null)return defaults();int schema=raw.get("schema").getAsInt();if(schema!=1&&schema!=2&&schema!=3&&schema!=4)throw new IllegalArgumentException("Versión de datos desconocida");var settings=raw.getAsJsonObject("settings");var gson=new Gson();for(String id:CompanionContent.IDS){var fallback=gson.toJsonTree(defaults().settings().get(id)).getAsJsonObject();if(schema<4){fallback.addProperty("maxHealth",fallback.get("maxHealth").getAsDouble()/1.5);fallback.addProperty("armor",fallback.get("armor").getAsDouble()/1.5);}if(schema<3){fallback.addProperty("reviveSeconds",300);fallback.addProperty("supportCooldown",45);fallback.addProperty("supportDuration",30);}if(!settings.has(id))settings.add(id,fallback);else for(var entry:fallback.entrySet())if(!settings.getAsJsonObject(id).has(entry.getKey()))settings.getAsJsonObject(id).add(entry.getKey(),entry.getValue());if(schema==1){settings.getAsJsonObject(id).addProperty("supportCooldown",45);settings.getAsJsonObject(id).addProperty("supportDuration",30);}}if(schema<3){Path backup=file.resolveSibling(file.getFileName()+".before-shadow-upgrades.json");if(!java.nio.file.Files.exists(backup))java.nio.file.Files.copy(file,backup);for(var entry:settings.entrySet()){var row=entry.getValue().getAsJsonObject();row.addProperty("reviveSeconds",Math.min(86400,row.get("reviveSeconds").getAsInt()*2));row.addProperty("supportCooldown",Math.min(7200,row.get("supportCooldown").getAsInt()*2));row.addProperty("supportDuration",Math.max(1,row.get("supportDuration").getAsInt()/2));}}if(schema<4){Path backup=file.resolveSibling(file.getFileName()+".before-companion-vitality.json");if(!java.nio.file.Files.exists(backup))java.nio.file.Files.copy(file,backup);for(var entry:settings.entrySet()){var row=entry.getValue().getAsJsonObject();row.addProperty("maxHealth",Math.min(4000,row.get("maxHealth").getAsDouble()*1.5));row.addProperty("armor",Math.min(30,row.get("armor").getAsDouble()*1.5));}}raw.addProperty("schema",4);return gson.fromJson(raw,Data.class);}
 long now(){return clock.getAsLong();}
 private void requireReady(){if(!ready)throw new IllegalArgumentException("Compañeros no disponibles; revisa el registro del servidor");}
 CompanionUpgrades.Levels upgrades(UUID owner,String id){return owner(owner).upgrades().getOrDefault(id,CompanionUpgrades.Levels.ZERO);}
 PetConfig effective(UUID owner,String id){var c=config(id);var u=upgrades(owner,id);return new PetConfig(c.enabled(),c.permission(),Math.max(10,(int)Math.round(c.reviveSeconds()*(1-.05*u.revive()))),Math.min(4000,c.maxHealth()*(1+.1*u.health())),c.speed(),c.support(),Math.max(10,(int)Math.round(c.supportCooldown()*(1-.05*u.cooldown()))),Math.min(30,c.armor()*(1+.1*u.armor())),c.ranged(),Math.min(64,c.attackDamage()*(1+.1*u.damage())),c.attackCooldown(),Math.min(30,(int)Math.round(c.supportDuration()*(1+.1*u.duration()))));}
 void upgrade(ServerPlayer p,String id,String material){requireReady();if(!p.isAlive()||p.isSpectator()||!allowed(p,id))throw new IllegalArgumentException("Compañero no disponible");var a=active.get(p.getUUID());if(a!=null&&a.id().equals(id))throw new IllegalArgumentException("Guarda este compañero antes de mejorarlo");var state=life(p.getUUID(),id);if(state.dead(now()))throw new IllegalArgumentException("Espera a que reviva antes de mejorarlo");var m=CompanionUpgrades.material(material);var levels=upgrades(p.getUUID(),id);var next=levels.add(m.stat(),m.points());if(next.equals(levels))throw new IllegalArgumentException("Esta mejora ya alcanzó el máximo");var item=CompanionUpgrades.ITEMS.get(material).get();int slot=-1;for(int n=0;n<p.getInventory().getContainerSize();n++)if(p.getInventory().getItem(n).is(item)){slot=n;break;}if(slot<0)throw new IllegalArgumentException("Necesitas ese material en tu inventario");var old=data;var owners=new LinkedHashMap<>(data.owners());var o=owner(p.getUUID());var map=new LinkedHashMap<>(o.upgrades());map.put(id,next);owners.put(p.getUUID(),new OwnerData(o.pets(),o.grants(),map));var consumed=p.getInventory().removeItem(slot,1);data=new Data(4,data.settings(),owners);try{flush();}catch(RuntimeException ex){data=old;if(p.getInventory().getItem(slot).isEmpty())p.getInventory().setItem(slot,consumed);else p.getInventory().getItem(slot).grow(1);throw ex;}p.getInventory().setChanged();p.containerMenu.broadcastChanges();}
 PetConfig config(String id){if(!CompanionContent.IDS.contains(id))throw new IllegalArgumentException("Compañero desconocido");return data.settings().get(id);}
 OwnerData owner(UUID player){return data.owners().getOrDefault(player,new OwnerData(Map.of(),Map.of()));}
 CompanionLife life(UUID player,String id){var c=effective(player,id);return owner(player).pets().getOrDefault(id,new CompanionLife(c.maxHealth(),0,0)).revived(c.maxHealth(),now());}
 private void setLife(UUID player,String id,CompanionLife life){var owners=new LinkedHashMap<>(data.owners());var o=owner(player);var pets=new LinkedHashMap<>(o.pets());pets.put(id,life);owners.put(player,new OwnerData(pets,o.grants(),o.upgrades()));data=new Data(4,data.settings(),owners);}
 void grant(UUID player,String id,long until){requireReady();config(id);var owners=new LinkedHashMap<>(data.owners());var o=owner(player);var grants=new LinkedHashMap<>(o.grants());if(until==0)grants.remove(id);else grants.put(id,until);owners.put(player,new OwnerData(o.pets(),grants,o.upgrades()));data=new Data(4,data.settings(),owners);flush();}
 void revoke(UUID owner,String id){grant(owner,id,0);var a=active.get(owner);if(a!=null&&a.id().equals(id))store(owner,false);}
 boolean allowed(ServerPlayer p,String id){return ready&&config(id).enabled()&&CompanionLife.unlocked(owner(p.getUUID()).grants().getOrDefault(id,0L),now());}
 void flush(){if(server==null||data==null)return;try{AtomicJson.write(file,data);}catch(Exception ex){ready=false;for(var a:List.copyOf(active.values())){var e=a.level().getEntity(a.entity());if(e!=null)e.discard();}active.clear();ZianMobs.LOGGER.error("Companions disabled after a persistence failure",ex);throw new IllegalStateException("No se pudo guardar: compañeros desactivados para proteger los datos",ex);}}
 private void tick(ServerTickEvent.Post event){if(!ready||event.getServer()!=server||server.getTickCount()%20!=0)return;try{for(var entry:List.copyOf(active.entrySet())){var p=server.getPlayerList().getPlayer(entry.getKey());var a=entry.getValue();var e=a.level().getEntity(a.entity());if(!(e instanceof CompanionEntity pet)||!pet.isAlive()){if(e==null)active.remove(entry.getKey());continue;}if(p==null||!p.isAlive()||p.isSpectator()||p.serverLevel()!=a.level()||!allowed(p,a.id())){store(entry.getKey(),false);if(p!=null)p.sendSystemMessage(Component.literal("Tu compañero volvió al refugio: su desbloqueo no está activo o has cambiado de estado."));}}}catch(Exception ex){ZianMobs.LOGGER.error("Companion access tick failed",ex);}}
 void checkAccess(ServerPlayer player){var a=active.get(player.getUUID());if(a!=null&&(!player.isAlive()||player.isSpectator()||player.serverLevel()!=a.level()||!allowed(player,a.id())))store(player.getUUID(),false);}
 public void request(ServerPlayer p,String section,String id){if(!section.startsWith("companion"))return;try{requireReady();long t=now();if(t-rate.getOrDefault(p.getUUID(),0L)<150)return;rate.put(p.getUUID(),t);open(p,section,id,"");}catch(Exception ex){p.sendSystemMessage(Component.literal(ex.getMessage()==null?"No se pudo abrir el panel":ex.getMessage()));}}
 public void action(ServerPlayer p,MobsNetwork.PetAction packet){try{requireReady();var session=sessions.consume(p.getUUID(),packet.token(),now(),revision);var values=JsonParser.parseString(packet.json()).getAsJsonObject();if(values.size()>12)throw new IllegalArgumentException("Formulario demasiado grande");String section=session.section(),id=session.id();String op=packet.operation();
   if(section.equals("companions")){if(!p.isAlive()||p.isSpectator())throw new IllegalArgumentException("Debes estar vivo para usar compañeros");switch(op){case "summon"->summon(p,id);case "store"->store(p.getUUID(),true);case "bring"->{if(!allowed(p,id))throw new IllegalArgumentException("Este compañero no está desbloqueado");var a=active.get(p.getUUID());if(a==null||!a.id().equals(id)||!(a.level().getEntity(a.entity()) instanceof CompanionEntity pet)||!pet.isAlive())throw new IllegalArgumentException("Este compañero no está activo");if(!place(pet,p))throw new IllegalArgumentException("No hay un lugar seguro cerca de ti");}default->throw new IllegalArgumentException("Acción desconocida");}open(p,"companions",id,"");return;}
   if(section.equals("companion_upgrades")&&op.equals("upgrade")){String material=text(values,"material");String notice;try{upgrade(p,id,material);notice="Mejora aplicada. El vínculo ha crecido.";}catch(IllegalArgumentException ex){notice=ex.getMessage();}MobsNetwork.send(p,new MobsNetwork.JsonView(upgradeView(p,id,material,notice).toString()));return;}

  if(!p.hasPermissions(2))throw new IllegalArgumentException("Solo un administrador puede cambiar estos ajustes");
   if(section.equals("companion_settings")&&op.equals("save")){var old=config(id);var next=new PetConfig(Boolean.parseBoolean(text(values,"enabled")),old.permission(),Integer.parseInt(text(values,"revive")),Double.parseDouble(text(values,"health")),Double.parseDouble(text(values,"speed")),Boolean.parseBoolean(text(values,"support")),Integer.parseInt(text(values,"supportCooldown")),Double.parseDouble(text(values,"armor")),Boolean.parseBoolean(text(values,"ranged")),Double.parseDouble(text(values,"attackDamage")),Integer.parseInt(text(values,"attackCooldown")),Integer.parseInt(text(values,"supportDuration")));var settings=new LinkedHashMap<>(data.settings());settings.put(id,next);data=new Data(4,settings,data.owners());revision=new Object();flush();for(var entry:List.copyOf(active.entrySet()))if(entry.getValue().id().equals(id))store(entry.getKey(),false);open(p,section,id,"Ajustes guardados; los compañeros activos volvieron al refugio.");return;}
   if(section.equals("companion_access")&&(op.equals("grant")||op.equals("revoke"))){UUID target=UUID.fromString(text(values,"player"));String pet=text(values,"pet");int seconds=Integer.parseInt(text(values,"duration"));if(seconds!=0&&(seconds<10||seconds>31536000))throw new IllegalArgumentException("Duración: 0 permanente, o 10–31536000 segundos");if(op.equals("revoke"))revoke(target,pet);else grant(target,pet,seconds==0?Long.MAX_VALUE:Math.addExact(now(),seconds*1000L));open(p,section,"","Desbloqueo del compañero actualizado.");return;}
   throw new IllegalArgumentException("Acción no permitida");
  }catch(Exception ex){p.sendSystemMessage(Component.literal(ex.getMessage()==null?"Operación rechazada":ex.getMessage()));if(ready)open(p,"companions","",ex.getMessage()==null?"Operación rechazada":ex.getMessage());}}
 private static String text(JsonObject values,String key){if(!values.has(key)||!values.get(key).isJsonPrimitive())throw new IllegalArgumentException("Falta el campo "+key);return values.get(key).getAsString();}
 void summon(ServerPlayer player,String id){requireReady();if(!player.isAlive()||player.isSpectator()||!allowed(player,id))throw new IllegalArgumentException("Un administrador debe desbloquear este compañero");var state=life(player.getUUID(),id);if(state.dead(now()))throw new IllegalArgumentException("Debe descansar antes de revivir");var old=active.get(player.getUUID());if(old!=null&&old.id().equals(id))throw new IllegalArgumentException("Ya tienes este compañero invocado");var entity=CompanionContent.PETS.get(id).get().create(player.serverLevel());if(entity==null)throw new IllegalStateException("No se pudo crear el compañero");var c=effective(player.getUUID(),id);entity.ownerId=player.getUUID();entity.managed=true;entity.getAttribute(Attributes.MAX_HEALTH).setBaseValue(c.maxHealth());entity.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(c.speed());entity.getAttribute(Attributes.FLYING_SPEED).setBaseValue(c.speed());entity.getAttribute(Attributes.ARMOR).setBaseValue(c.armor());entity.setHealth((float)Math.min(c.maxHealth(),state.health()));if(!place(entity,player)){entity.discard();throw new IllegalArgumentException("No hay espacio aéreo libre cerca de ti");}if(old!=null)store(player.getUUID(),false);setLife(player.getUUID(),id,state);flush();if(!player.serverLevel().addFreshEntity(entity))throw new IllegalStateException("El servidor rechazó la aparición");active.put(player.getUUID(),new Active(entity.getUUID(),id,player.serverLevel(),entity));}
 boolean place(CompanionEntity entity,ServerPlayer owner){var target=CompanionFlightTargets.find(entity,owner,false);if(target==null)return false;entity.moveTo(target.x,target.y,target.z,owner.getYRot(),0);entity.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);entity.getNavigation().stop();return true;}

 void store(UUID owner,boolean heal){var a=active.get(owner);if(a==null)return;var pet=a.pet();pet.cancelAttack();if(pet.isAlive()){var previous=life(owner,a.id());setLife(owner,a.id(),new CompanionLife(pet.getHealth(),previous.reviveAt(),previous.supportAt(),previous.attackAt()).stored(effective(owner,a.id()).maxHealth(),heal));flush();pet.discard();}active.remove(owner);}
 void capture(CompanionEntity pet){if(!ready||pet.ownerId==null||!pet.isAlive())return;var a=active.get(pet.ownerId);if(a==null||!a.entity().equals(pet.getUUID()))return;var old=life(pet.ownerId,pet.id());setLife(pet.ownerId,pet.id(),new CompanionLife(pet.getHealth(),old.reviveAt(),old.supportAt(),old.attackAt()));flush();}
 void died(CompanionEntity pet){if(!ready||pet.ownerId==null)return;var a=active.get(pet.ownerId);if(a==null||!a.entity().equals(pet.getUUID()))return;setLife(pet.ownerId,pet.id(),life(pet.ownerId,pet.id()).died(now(),effective(pet.ownerId,pet.id()).reviveSeconds()));flush();active.remove(pet.ownerId);var p=server.getPlayerList().getPlayer(pet.ownerId);if(p!=null)p.sendSystemMessage(Component.literal(CompanionContent.name(pet.id())+" volverá a estar listo en "+effective(pet.ownerId,pet.id()).reviveSeconds()+" s."));}
 void entityTick(CompanionEntity pet){if(pet.owner() instanceof ServerPlayer owner)tetherTick(pet,owner);}
 void tetherTick(CompanionEntity pet,ServerPlayer owner){if(!ready||pet.ownerId==null||!owner.getUUID().equals(pet.ownerId))return;var a=active.get(pet.ownerId);if(a==null||!a.entity().equals(pet.getUUID()))return;if(pet.distanceToSqr(owner)>32*32){store(pet.ownerId,false);distanceNotice(owner,pet.id());return;}if(!allowed(owner,pet.id())||!owner.isAlive()){store(pet.ownerId,false);return;}if(pet.distanceToSqr(owner)>16*16){pet.outsideFollowTicks++;if(pet.outsideFollowTicks>=20&&pet.tickCount-pet.lastRescueTick>=20){pet.lastRescueTick=pet.tickCount;if(place(pet,owner)){pet.cancelAttack();pet.outsideFollowTicks=0;}}}else pet.outsideFollowTicks=0;advanceAttack(pet,owner);if(pet.tickCount%10==0)attack(pet,owner);if(pet.tickCount%20==0)support(pet,owner);}
 String lastSupportNotice="";
 final Random supportRandom=new Random();
 List<net.minecraft.core.Holder<MobEffect>> supportPool(String id){if(id.equals("ghost"))return List.of(MobEffects.SLOW_FALLING,MobEffects.NIGHT_VISION,MobEffects.MOVEMENT_SPEED);if(id.contains("fire")||id.contains("tnt"))return List.of(MobEffects.FIRE_RESISTANCE,MobEffects.DAMAGE_RESISTANCE,MobEffects.DAMAGE_BOOST);if(id.contains("water")||id.equals("otter"))return List.of(MobEffects.REGENERATION,MobEffects.WATER_BREATHING,MobEffects.MOVEMENT_SPEED);if(id.equals("kit"))return List.of(MobEffects.DAMAGE_RESISTANCE,MobEffects.DAMAGE_BOOST,MobEffects.ABSORPTION);if(id.equals("clank"))return List.of(MobEffects.ABSORPTION,MobEffects.DAMAGE_RESISTANCE,MobEffects.MOVEMENT_SPEED);return List.of(MobEffects.REGENERATION,MobEffects.DAMAGE_RESISTANCE,MobEffects.MOVEMENT_SPEED);}
 void support(CompanionEntity pet,ServerPlayer owner){var a=active.get(owner.getUUID());if(a==null||!a.entity().equals(pet.getUUID())||!owner.getUUID().equals(pet.ownerId)||!allowed(owner,pet.id())||!pet.isAlive()||!owner.isAlive()||pet.distanceToSqr(owner)>16*16)return;var state=life(pet.ownerId,pet.id());var cfg=effective(owner.getUUID(),pet.id());if(!cfg.support()||state.supportAt()>now())return;boolean injured=owner.getHealth()<owner.getMaxHealth(),danger=owner.getLastHurtByMob()!=null&&owner.tickCount-owner.getLastHurtByMobTimestamp()<100;if(!injured&&!danger&&owner.fallDistance<=3)return;var candidates=new ArrayList<>(supportPool(pet.id()));candidates.removeIf(effect->owner.hasEffect(effect)||effect==MobEffects.REGENERATION&&!injured);Collections.shuffle(candidates,supportRandom);int count=1+supportRandom.nextInt(2);var applied=new ArrayList<String>();for(var effect:candidates){if(applied.size()>=count)break;if(owner.addEffect(new MobEffectInstance(effect,cfg.supportDuration()*20,0),pet))applied.add(effectName(effect)+" I");}if(!applied.isEmpty()){setLife(pet.ownerId,pet.id(),new CompanionLife(pet.getHealth(),0,now()+cfg.supportCooldown()*1000L,state.attackAt()));flush();var message=Component.literal("✦ ").withStyle(net.minecraft.ChatFormatting.GOLD).append(Component.literal(CompanionContent.name(pet.id())).withStyle(net.minecraft.ChatFormatting.AQUA,net.minecraft.ChatFormatting.BOLD)).append(Component.literal(" te ha apoyado con\n").withStyle(net.minecraft.ChatFormatting.GRAY)).append(Component.literal("  ✧ ").withStyle(net.minecraft.ChatFormatting.GOLD)).append(Component.literal(String.join(" + ",applied)).withStyle(net.minecraft.ChatFormatting.GREEN)).append(Component.literal(" · durante "+cfg.supportDuration()+" segundos").withStyle(net.minecraft.ChatFormatting.GOLD));lastSupportNotice=message.getString();owner.sendSystemMessage(message);}}
 private static void distanceNotice(ServerPlayer owner,String id){owner.sendSystemMessage(Component.literal("✦ Refugio » ").withStyle(net.minecraft.ChatFormatting.GOLD).append(Component.literal(CompanionContent.name(id)).withStyle(net.minecraft.ChatFormatting.AQUA)).append(Component.literal("\n  Se ha guardado al superar los 32 bloques de distancia.").withStyle(net.minecraft.ChatFormatting.GRAY)));}
 private static String effectName(net.minecraft.core.Holder<MobEffect> effect){if(effect==MobEffects.REGENERATION)return "Regeneración";if(effect==MobEffects.DAMAGE_RESISTANCE)return "Resistencia";if(effect==MobEffects.ABSORPTION)return "Absorción";if(effect==MobEffects.MOVEMENT_SPEED)return "Velocidad";if(effect==MobEffects.DAMAGE_BOOST)return "Fuerza";if(effect==MobEffects.NIGHT_VISION)return "Visión nocturna";if(effect==MobEffects.SLOW_FALLING)return "Caída lenta";if(effect==MobEffects.FIRE_RESISTANCE)return "Resistencia al fuego";return "Respiración acuática";}
 boolean validTarget(CompanionEntity pet,ServerPlayer owner,LivingEntity target){return target!=null&&target.isAlive()&&target instanceof net.minecraft.world.entity.Mob&&!(target instanceof CompanionEntity)&&!(target instanceof net.minecraft.world.entity.OwnableEntity)&&!owner.isAlliedTo(target)&&!pet.isAlliedTo(target)&&owner.distanceToSqr(target)<=12*12&&pet.distanceToSqr(target)<=12*12&&pet.hasLineOfSight(target)&&owner.hasLineOfSight(target);}
 void attack(CompanionEntity pet,ServerPlayer owner){var a=active.get(owner.getUUID());if(a==null||!a.entity().equals(pet.getUUID())||!allowed(owner,pet.id())||!pet.isAlive()||!owner.isAlive()||pet.pendingAttack!=null||pet.distanceToSqr(owner)>16*16)return;var cfg=effective(owner.getUUID(),pet.id());var state=life(owner.getUUID(),pet.id());if(!cfg.ranged()||cfg.attackDamage()<=0||state.attackAt()>now())return;LivingEntity target=null;if(owner.tickCount-owner.getLastHurtMobTimestamp()<200&&validTarget(pet,owner,owner.getLastHurtMob()))target=owner.getLastHurtMob();if(target==null&&owner.tickCount-owner.getLastHurtByMobTimestamp()<200&&validTarget(pet,owner,owner.getLastHurtByMob()))target=owner.getLastHurtByMob();if(target==null&&pet.tickCount-pet.getLastHurtByMobTimestamp()<200&&validTarget(pet,owner,pet.getLastHurtByMob()))target=pet.getLastHurtByMob();if(target==null)target=owner.serverLevel().getEntitiesOfClass(net.minecraft.world.entity.Mob.class,owner.getBoundingBox().inflate(12),mob->(mob.getTarget()==owner||mob.getTarget()==pet)&&validTarget(pet,owner,mob)).stream().min(Comparator.comparingDouble(pet::distanceToSqr)).orElse(null);if(target==null)return;
  var profile=CompanionAttacks.profile(pet.id());setLife(owner.getUUID(),pet.id(),new CompanionLife(pet.getHealth(),state.reviveAt(),state.supportAt(),now()+cfg.attackCooldown()*1000L));flush();pet.pendingAttack=new CompanionAttacks.Pending(target.getUUID(),pet.tickCount,profile,(float)cfg.attackDamage());pet.getNavigation().stop();face(pet,target);if(!profile.clip().isEmpty())pet.triggerAnim("combat","ranged");advanceAttack(pet,owner);
 }
 private static void face(CompanionEntity pet,LivingEntity target){pet.getLookControl().setLookAt(target,360,360);float yaw=(float)(Math.atan2(target.getZ()-pet.getZ(),target.getX()-pet.getX())*180/Math.PI)-90;pet.setYRot(yaw);pet.setYBodyRot(yaw);pet.setYHeadRot(yaw);}
 void advanceAttack(CompanionEntity pet,ServerPlayer owner){var task=pet.pendingAttack;if(task==null)return;var a=active.get(owner.getUUID());var entity=owner.serverLevel().getEntity(task.target);if(a==null||!a.entity().equals(pet.getUUID())||!pet.isAlive()||!owner.isAlive()||owner.serverLevel()!=pet.level()||!allowed(owner,pet.id())||pet.distanceToSqr(owner)>16*16||!config(pet.id()).ranged()||!(entity instanceof LivingEntity target)||!validTarget(pet,owner,target)){pet.cancelAttack();return;}face(pet,target);pet.getNavigation().stop();int elapsed=pet.tickCount-task.started;
  while(task.released<task.profile.impacts().size()&&elapsed>=task.profile.impacts().get(task.released)){task.released++;release(pet,owner,target,task.damage/task.profile.impacts().size());if(!target.isAlive()){pet.cancelAttack();return;}}
  if(elapsed>=task.profile.duration())pet.cancelAttack();
 }
 private void release(CompanionEntity pet,ServerPlayer owner,LivingEntity target,float damage){var start=pet.getEyePosition();var end=target.getBoundingBox().getCenter();var delta=end.subtract(start);var particle=pet.id().contains("snow")||pet.id().equals("gift")?net.minecraft.core.particles.ParticleTypes.SNOWFLAKE:pet.id().contains("fire")?net.minecraft.core.particles.ParticleTypes.FLAME:net.minecraft.core.particles.ParticleTypes.ENCHANT;for(int i=0;i<=16;i++){var at=start.add(delta.scale(i/16.0));owner.serverLevel().sendParticles(particle,at.x,at.y,at.z,1,0,0,0,0);}boolean accepted=target.hurt(pet.damageSources().indirectMagic(pet,owner),damage);if(accepted&&target.isAlive()&&target instanceof net.minecraft.world.entity.Mob mob&&!(mob instanceof net.minecraft.world.entity.OwnableEntity)&&!mob.isAlliedTo(pet)){mob.setLastHurtByMob(pet);if(mob instanceof net.minecraft.world.entity.monster.Enemy&&mob.canAttack(pet)&&mob.hasLineOfSight(pet))mob.setTarget(pet);}}

 private JsonObject base(ServerPlayer p,String section,String id,String title,String notice){var d=new JsonObject();d.addProperty("section",section);d.addProperty("id",id);d.addProperty("title",title);d.addProperty("notice",notice==null?"":notice);d.addProperty("token",sessions.issue(p.getUUID(),section,id,now(),revision).token().toString());return d;}
 JsonObject snapshot(ServerPlayer p,String section,String id,String notice){requireReady();if(section.equals("companions")){if(!CompanionContent.IDS.contains(id))id=CompanionContent.IDS.stream().filter(key->allowed(p,key)).findFirst().orElse(CompanionContent.IDS.getFirst());var d=base(p,section,id,"Compañeros · Refugio",notice);d.addProperty("admin",p.hasPermissions(2));var rows=new JsonArray();for(String key:CompanionContent.IDS){var cfg=effective(p.getUUID(),key);var state=life(p.getUUID(),key);var row=new JsonObject();row.addProperty("id",key);row.addProperty("name",CompanionContent.name(key));row.addProperty("allowed",allowed(p,key));row.addProperty("permission","Desbloqueo del administrador");row.addProperty("armor",cfg.armor());row.addProperty("attackDamage",cfg.attackDamage());row.addProperty("ranged",cfg.ranged());row.addProperty("remaining",Math.max(0,state.reviveAt()-now()));row.addProperty("health",state.health());row.addProperty("maxHealth",cfg.maxHealth());var a=active.get(p.getUUID());row.addProperty("active",a!=null&&a.id().equals(key));if(a!=null&&a.id().equals(key)&&a.level().getEntity(a.entity()) instanceof CompanionEntity pet)row.addProperty("health",pet.getHealth());row.addProperty("support",cfg.support()?"1 o 2 apoyos al azar · "+cfg.supportDuration()+" s · espera "+cfg.supportCooldown()+" s":"Habilidad de apoyo desactivada");row.addProperty("supportWait",Math.max(0,state.supportAt()-now()));rows.add(row);}d.add("pets",rows);return d;}
  if(section.equals("companion_upgrades")){if(!allowed(p,id))throw new IllegalArgumentException("Este compañero no está desbloqueado");var d=base(p,section,id,"Vínculo · "+CompanionContent.name(id),notice);form(d);d.addProperty("saveButton",false);d.addProperty("notice",notice==null||notice.isBlank()?"Mejoras permanentes · consume 1 material · máximo 10 niveles":notice);var u=upgrades(p.getUUID(),id);var c=effective(p.getUUID(),id);String[] keys={"health","damage","armor","duration","cooldown","revive"};String[] labels={"Vida máxima","Daño","Armadura","Duración del apoyo","Espera del apoyo","Resurrección"};double[] stats={c.maxHealth(),c.attackDamage(),c.armor(),c.supportDuration(),c.supportCooldown(),c.reviveSeconds()};for(int n=0;n<keys.length;n++){field(d,keys[n],labels[n],"text",String.format(java.util.Locale.ROOT,"%.1f%s · nivel %d/10",stats[n],n>=3?" s":"",u.get(keys[n])));lastField(d).addProperty("readonly",true);lastField(d).addProperty("group",n<3?"Combate":"Habilidades");}d.addProperty("backId",id);field(d,"material","Material del inventario","choice",CompanionUpgrades.CATALOG.getFirst().id());var choices=new JsonArray();for(var m:CompanionUpgrades.CATALOG)choices.add(choice(m.id(),m.name()+" · "+CompanionUpgrades.label(m.stat())+" · tienes "+p.getInventory().countItem(CompanionUpgrades.ITEMS.get(m.id()).get())));lastField(d).add("choices",choices);action(d,"upgrade","Consumir material y mejorar");return d;}
  if(!p.hasPermissions(2))throw new IllegalArgumentException("Necesitas permiso de administrador");if(section.equals("companion_settings")){var c=config(id);var d=base(p,section,id,"Ajustes · "+CompanionContent.name(id),notice);form(d);field(d,"enabled","Compañero disponible","bool",c.enabled());field(d,"armor","Defensa de armadura (0–30)","text",c.armor());field(d,"revive","Resurrección (segundos)","text",c.reviveSeconds());field(d,"health","Vida máxima","text",c.maxHealth());field(d,"speed","Velocidad de movimiento","text",c.speed());field(d,"support","Habilidad de apoyo","bool",c.support());field(d,"supportCooldown","Espera de apoyo (segundos)","text",c.supportCooldown());field(d,"supportDuration","Duración del apoyo (1–30 segundos)","text",c.supportDuration());field(d,"ranged","Ataque a distancia","bool",c.ranged());field(d,"attackDamage","Daño a distancia (0–32)","text",c.attackDamage());field(d,"attackCooldown","Espera de ataque (segundos)","text",c.attackCooldown());return d;}
  if(section.equals("companion_access")){var d=base(p,section,"","Desbloquear compañeros",notice);form(d);d.addProperty("notice","El administrador desbloquea cada compañero. Puedes retirarlo cuando quieras.");d.addProperty("saveButton",false);var players=new JsonArray();for(var player:server.getPlayerList().getPlayers())players.add(choice(player.getUUID().toString(),player.getScoreboardName()));if(players.isEmpty())players.add(choice(p.getUUID().toString(),p.getScoreboardName()));field(d,"player","Jugador conectado","choice",p.getUUID());lastField(d).add("choices",players);var pets=new JsonArray();for(var key:CompanionContent.IDS)pets.add(choice(key,CompanionContent.name(key)));field(d,"pet","Compañero","choice","otter");lastField(d).add("choices",pets);field(d,"duration","Duración del acceso (segundos)","text",3600);action(d,"grant","Desbloquear compañero");action(d,"revoke","Retirar compañero");return d;}
  throw new IllegalArgumentException("Panel desconocido");
 }
 private static void form(JsonObject d){d.addProperty("back","companions");d.add("fields",new JsonArray());d.add("values",new JsonObject());d.add("actions",new JsonArray());}
 private static JsonObject choice(String id,String name){var d=new JsonObject();d.addProperty("id",id);d.addProperty("name",name);return d;}
 private static void field(JsonObject d,String key,String label,String kind,Object value){var f=new JsonObject();f.addProperty("key",key);f.addProperty("label",label);f.addProperty("kind",kind);f.addProperty("group","Básico");d.getAsJsonArray("fields").add(f);d.getAsJsonObject("values").addProperty(key,String.valueOf(value));}
 private static JsonObject lastField(JsonObject d){return d.getAsJsonArray("fields").get(d.getAsJsonArray("fields").size()-1).getAsJsonObject();}
 private static void action(JsonObject d,String id,String name){var a=choice(id,name);a.addProperty("label",name);a.addProperty("group","Básico");d.getAsJsonArray("actions").add(a);}
 JsonObject upgradeView(ServerPlayer p,String id,String material,String notice){var next=snapshot(p,"companion_upgrades",id,notice);if(CompanionUpgrades.ITEMS.containsKey(material))next.getAsJsonObject("values").addProperty("material",material);return next;}
 void open(ServerPlayer p,String section,String id,String notice){MobsNetwork.send(p,new MobsNetwork.JsonView(snapshot(p,section,id,notice).toString()));}
 CompanionEntity activeEntity(UUID owner){var a=active.get(owner);return a!=null&&a.level().getEntity(a.entity()) instanceof CompanionEntity pet?pet:null;}
}
